/**
 * Retorna o HTML de um ícone Lucide inline.
 *
 * @param string $name Nome do ícone.
 * @param string $class Classes adicionais para o SVG.
 * @return string HTML do SVG ou string vazia se o ícone não existir.
 */
function houzez_dash_icon( $name, $class = 'h-5 w-5' ) {
    $icons = houzez_dash_icons();

    if ( ! isset( $icons[ $name ] ) ) {
        return '';
    }

    $class = preg_replace( '/[^A-Za-z0-9_\-\s]/', '', $class );
    if ( '' === $class ) {
        $class = 'h-5 w-5';
    }

    return sprintf(
        '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="%s" aria-hidden="true" focusable="false">%s</svg>',
        esc_attr( $class ),
        $icons[ $name ]
    );
}
